import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../services/supabase_service.dart';
import '../zenex_ui.dart';

class ChatPage extends StatefulWidget{const ChatPage({super.key});@override State<ChatPage>createState()=>_ChatPageState();}
class _ChatPageState extends State<ChatPage>{final controller=TextEditingController();final scroll=ScrollController();List<Map<String,dynamic>>messages=[];String? conversationId;RealtimeChannel? channel;bool loading=true,sending=false;@override void initState(){super.initState();initChat();}Future<void>initChat()async{try{conversationId=await SupabaseService.getOrCreateSupportChat();await load();await SupabaseService.markSupportMessagesRead(conversationId!);channel=SupabaseService.supportChatChannel(conversationId!,onMessage:()async{await load();await SupabaseService.markSupportMessagesRead(conversationId!);});}catch(e){if(mounted)msg('$e');}finally{if(mounted)setState(()=>loading=false);}}Future<void>load()async{if(conversationId==null)return;final data=await SupabaseService.supportMessages(conversationId!);if(mounted){setState(()=>messages=data);WidgetsBinding.instance.addPostFrameCallback((_)=>scrollBottom());}}void scrollBottom(){if(scroll.hasClients)scroll.animateTo(scroll.position.maxScrollExtent,duration:const Duration(milliseconds:220),curve:Curves.easeOut);}Future<void>send()async{final text=controller.text.trim();if(text.isEmpty||sending||conversationId==null)return;setState(()=>sending=true);try{await SupabaseService.sendSupportMessage(conversationId:conversationId!,message:text);controller.clear();await load();}catch(e){if(mounted)msg('$e');}finally{if(mounted)setState(()=>sending=false);}}void msg(String x)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(x.replaceFirst('Exception: ','')),behavior:SnackBarBehavior.floating));String time(dynamic v){try{final d=DateTime.parse('$v').toLocal();final h=d.hour==0?12:d.hour>12?d.hour-12:d.hour;return '$h:${d.minute.toString().padLeft(2,'0')} ${d.hour>=12?'PM':'AM'}';}catch(_){return '';}}bool mine(Map<String,dynamic>m)=>m['sender_id']==Supabase.instance.client.auth.currentUser?.id;@override void dispose(){channel?.unsubscribe();controller.dispose();scroll.dispose();super.dispose();}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Row(children:[const IconTile(Icons.support_agent_rounded,color:kCyan),const SizedBox(width:10),const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('ZenexPay Support',style:TextStyle(fontSize:16,fontWeight:FontWeight.w900)),Text('Chat with Admin',style:TextStyle(fontSize:10,color:Colors.grey))])]),actions:[IconButton(onPressed:loading?null:load,icon:const Icon(Icons.refresh_rounded))]),body:loading?const Center(child:CircularProgressIndicator()):Column(children:[Container(margin:const EdgeInsets.fromLTRB(14,10,14,4),padding:const EdgeInsets.all(13),decoration:BoxDecoration(color:kBlue.withOpacity(.08),borderRadius:BorderRadius.circular(16)),child:const Row(children:[Icon(Icons.info_outline_rounded,color:kBlue,size:19),SizedBox(width:8),Expanded(child:Text('Need help with a task, payment, withdrawal, or account issue? Message ZenexPay Admin.',style:TextStyle(fontSize:12,height:1.35))) ])),Expanded(child:messages.isEmpty?const EmptyState(icon:Icons.support_agent_rounded,title:'Start a conversation',message:'Send your question below. Admin can reply directly here.'):ListView.builder(controller:scroll,padding:const EdgeInsets.fromLTRB(14,14,14,20),itemCount:messages.length,itemBuilder:(_,i){final m=messages[i],isMine=mine(m);return Align(alignment:isMine?Alignment.centerRight:Alignment.centerLeft,child:Container(constraints:BoxConstraints(maxWidth:MediaQuery.sizeOf(context).width*.78),margin:const EdgeInsets.only(bottom:9),padding:const EdgeInsets.fromLTRB(14,10,14,8),decoration:BoxDecoration(color:isMine?const Color(0xFF386BFF):Theme.of(context).cardColor,borderRadius:BorderRadius.only(topLeft:const Radius.circular(18),topRight:const Radius.circular(18),bottomLeft:Radius.circular(isMine?18:4),bottomRight:Radius.circular(isMine?4:18)),border:Border.all(color:isMine?Colors.transparent:Theme.of(context).dividerColor)),child:Column(crossAxisAlignment:CrossAxisAlignment.end,children:[Align(alignment:Alignment.centerLeft,child:Text('${m['message']??''}',style:TextStyle(color:isMine?Colors.white:null,height:1.35))),const SizedBox(height:4),Text(time(m['created_at']),style:TextStyle(color:isMine?Colors.white60:Colors.grey,fontSize:9))])));}),),Container(padding:const EdgeInsets.fromLTRB(12,8,12,12),decoration:BoxDecoration(color:Theme.of(context).scaffoldBackgroundColor,border:Border(top:BorderSide(color:Theme.of(context).dividerColor))),child:Row(crossAxisAlignment:CrossAxisAlignment.end,children:[Expanded(child:TextField(controller:controller,maxLines:4,minLines:1,textInputAction:TextInputAction.newline,decoration:const InputDecoration(hintText:'Write a message...',prefixIcon:Icon(Icons.chat_bubble_outline_rounded)))),const SizedBox(width:8),Container(width:52,height:52,decoration:BoxDecoration(gradient:const LinearGradient(colors:[kBlue,kPurple]),borderRadius:BorderRadius.circular(16)),child:IconButton(onPressed:sending?null:send,icon:sending?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2,color:Colors.white)):const Icon(Icons.send_rounded,color:Colors.white)))])]) );}
